<template><el-card><template #header>在线订房</template><el-form :model="f" inline><el-form-item label="入住"><el-date-picker v-model="f.checkInDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="退房"><el-date-picker v-model="f.checkOutDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item><el-button type="primary" @click="search">查询可用床位</el-button></el-form-item></el-form><el-table :data="beds" border><el-table-column prop="roomNo" label="房间号"/><el-table-column prop="roomName" label="房间名称"/><el-table-column prop="bedNo" label="床位号"/><el-table-column prop="price" label="价格"/><el-table-column label="操作" width="100"><template #default><el-button size="small" type="success" @click="book">预订</el-button></template></el-table-column></el-table><el-alert v-if="orderId" :title="`订单创建成功，ID：${orderId}`" type="success" :closable="false" style="margin-top:12px"/></el-card></template>
<script setup lang="ts">
import { reactive, ref } from 'vue';import { getAvailableBedsByGender } from '../../api/bed';import { createOrder } from '../../api/order';import { getLoginUser } from '../../utils/auth';import { ElMessage } from 'element-plus'
const user=getLoginUser()!;const f=reactive({checkInDate:'',checkOutDate:''});const beds=ref<any[]>([]);const orderId=ref<number>()
const search=async()=>{beds.value=(await getAvailableBedsByGender({checkInDate:f.checkInDate,checkOutDate:f.checkOutDate,userGender:user.gender})).data||[]}
const book=async()=>{if(!f.checkInDate||!f.checkOutDate){ElMessage.warning('请选择日期');return}orderId.value=(await createOrder({userId:user.userId,checkInDate:f.checkInDate,checkOutDate:f.checkOutDate,userGender:user.gender,remark:'用户端下单'})).data;ElMessage.success('创建订单成功')}
</script>
